-- 悦航购商超分类扩充种子数据（Boot 单体 模式）
--
-- 目标库：aryn_boot（单体模式所有表同库）
-- 背景：参考生鲜电商分类页（新鲜水果/精选冻品/咖啡能量/文具体育等），补齐系统中缺失的
--       1 个一级类目 + 11 个二级类目，并新增 26 个代表商品，
--       全部配图回填 spu_urls / category_pic，登记 sys_material 素材库。
-- 图片实体：db/assets/extend-category-product-images/、db/assets/extend-category-images/（manifest.tsv 清单）
-- 部署方式：将 stored_file 图片放入文件存储根目录 /data/aryn/uploads/{TENANT}/；本脚本只写库。
-- 特性：可重复执行；仅按 98x 前缀与新增类目 id 幂等清理自身数据，不触碰存量业务数据；
--       逻辑删除字段 del_flag，禁止物理删除存量。
--
-- 执行：mysql -u root -p aryn_boot < 86extend_category_seed.sql

USE `aryn_boot`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 0. 幂等清理（仅本脚本 98x 前缀与新增类目，不触碰存量） ----------
DELETE FROM `goods_sku` WHERE `id` LIKE '9810000000000000%';
DELETE FROM `goods_spu` WHERE `id` LIKE '9800000000000000%';
DELETE FROM `sys_material` WHERE `id` LIKE '9820000000000000%' OR `id` LIKE '9830000000000000%';
DELETE FROM `goods_category` WHERE `id` IN ('9510000000000000013','9520000000000000055','9520000000000000056','9520000000000000057','9520000000000000058','9520000000000000059','9520000000000000060','9520000000000000061','9520000000000000062','9520000000000000063','9520000000000000064','9520000000000000065');

-- ---------- 1. 新增类目（1 一级 + 11 二级，直接回填 category_pic） ----------

-- ---------- 2. 新增商品 SPU（26 个，主图直接回填） ----------

-- ---------- 3. 新增默认 SKU（26 个） ----------

-- ---------- 4. 素材库登记（商品图 26 + 类目图 12） ----------

SET FOREIGN_KEY_CHECKS = 1;
